---@class RecipeDojo
---@field recipeId integer
---@field isCollect integer
---@field exp string
---@field rating integer 星级
local RecipeDojo = {}

---@return RecipeDojo
function RecipeDojo.New(recipeId, isCollect, exp, rating)
    ---@type RecipeDojo
    local this = {}
    setmetatable(this, { __index = RecipeDojo })
    this.recipeId = checkNumber(recipeId)
    this.isCollect = checkNumber(isCollect)
    this.exp = checkNumber(exp)
    this.rating = checkNumber(rating)
    return this
end
