function MaidCoffeePlayerComponent:CleanCD()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
    end
    self._timeDown = nil
    if not isNull(self.handler) then
        Events.RemoveListener(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, self.handler)
    end
    self.handler = nil
end

