---OrderInfoUpdate
---弹出页面现面后的逻辑处理
---@param t table
function MaidCoffeePlayerComponent:OrderInfoUpdate(t)
    if t then
        local data = t.data
        local isNewOrder = checkNumber(t.isNewOrder)
        if data then
            self.takeOutOrders[tostring(data.id)] = data
        end
        if isNewOrder == 1 then
            ----重新刷新一次新的订单
            ---领取完刷新一次全订单数据
            GameUtils.Request(Interfaces.MaidCoffeeTakeout, {}, function(req, response)
                if checkNumber(response.errCode) == 0 then
                    local rdata = checkTable(response.data)
                    self:UpdateTakeOutDailyTimes(checkTable(rdata.dailyTimes))
                    self:ResetTakeoutOrders(checkTable(rdata.takeOutOrders))

                end
            end)
        else
            self:ResetTakeoutOrders(self.takeOutOrders)
        end
    end
end

function MaidCoffeePlayerComponent:UpdateTakeOutDailyTimes(data)
    self.takeOutDailyTimes = checkTable(data)
end

