----IsAreaOrderMax
---区域订单是否达到最大次数
---@param areaId number 区域Id
function MaidCoffeePlayerComponent:IsAreaOrderMax(areaId)
    local vo = ActionUtils.GetRegionPrimaryMapVo(areaId)
    local timeLimitVo = CfUtils.GetCfVo(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",areaId)
    if vo then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local lv, _ = ActionUtils.GetRegionalPointLikabilityLevel(vo.id)
        if timeLimitVo then
            local maxCount = timeLimitVo.takeOutNum[lv]
            return self:GetTimeByArea(areaId) >= tonumber(maxCount)
        end
    end
    return false
end

function MaidCoffeePlayerComponent:IsAllAreaOrderCold(areaId)
    local allOrders = self:GetAllTakeoutOrders()
    for i, v in pairs(allOrders) do
        if v.area == areaId then
            if checkNumber(v.unlocked) == 1 and v.status ~= MaidCoffeeConstants.TakeOutStatus.Cold then
                return false
            end
        end
    end
    return true
end

---Initialize
---初始化经营的初始登录信息的数据
function MaidCoffeePlayerComponent:Initialize(data)
    self:Reset()
    if rawget(data,"recipes") then  -- @食谱
        local recipes = data.recipes
        if recipes and table.count(recipes) > 0 then
            for i, v in pairs(recipes) do
                local dojo = RecipeDojo.New(v.recipeId, v.isCollect, v.exp, v.rating)
                self.recipes[tostring(dojo.recipeId)] = dojo
                self.packet[tostring(dojo.recipeId)] = 1 --背包id与数量
            end
        end
    end

    if rawget(data,"foods") then  --@食材
        local foods = data.foods
        if foods and table.count(foods) > 0 then
            for goodsId, v in pairs(foods) do
                self.packet[tostring(goodsId)] = checkNumber(v) --背包id与数量
            end
        end
    end

    if rawget(data,"cooks") then --@料理
        local cooks = data.cooks
        if cooks and table.count(cooks) > 0 then
            for goodsId, v in pairs(cooks) do
                self.packet[tostring(goodsId)] = checkNumber(v) --背包id与数量
            end
        end
    end

    if rawget(data,"takeOutTeams") then -- @编队人员信息
        local teams = checkTable(data.takeOutTeams)
        if teams and table.count(teams) > 0 then
            for _, v in pairs(teams) do
                self.teams[tostring(v.teamId)] = {}
                local t = string.split(v.cards, ',') --背包id与数量
                if #t > 0 then
                    for i, id in pairs(t) do
                        if checkNumber(id) > 0 then
                            table.insert(self.teams[tostring(v.teamId)], checkNumber(id))
                        end
                    end
                end
            end
        end
    end

    if rawget(data,"cafeLevel") then --@餐厅等级
        self.cafeLevel = checkNumber(data.cafeLevel)
    end

    if rawget(data,"cafeStar") then --@餐厅星级
        self.cafeStar = checkNumber(data.cafeStar)
    end



    if rawget(data,"cafeExp") then --@餐厅经验
        self.cafeExp = checkNumber(data.cafeExp)
    end

    if rawget(data,"takeOutDailyTimes") then  --@区域外卖每日配送次数
        self:UpdateTakeOutDailyTimes(checkTable(data.takeOutDailyTimes))
        print('---->>>', table.dump(self.takeOutDailyTimes, false, 3))
    end

    if rawget(data,"allTakeoutTimes") then --@区域外卖总的配送次数
        self:UpdateTakeOutAllTimes(data.allTakeoutTimes)
    end

    if rawget(data,"takeOutOrders") then --table @外卖订单
        self:ResetTakeoutOrders(checkTable(data.takeOutOrders))
        local Events_Broadcast = function(eventName, ...)
            if Events.HasListener(eventName) then
                Events.Broadcast(eventName, ...)
            end
        end
        if data.takeOutOrders then
            self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id, Elapsed)
                if self.takeOutOrders then
                    for orderId, data in pairs(self.takeOutOrders) do
                        if checkInt(data.status) == MaidCoffeeConstants.TakeOutStatus.PROGRESSING then
                            data.remainTime = checkInt(data.remainTime) - Elapsed
                            if data.remainTime <= 0 then
                                data.status = MaidCoffeeConstants.TakeOutStatus.FINISHED
                                ----变成已完成
                                Events_Broadcast(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, orderId, 1)
                            else
                                if checkInt(data.remainTime) > 0 then
                                    --local text = string.format_size_tag(string.format_color_tag(second_toHHMMSS(data.remainTime), '#d7184a'), 42)
                                    Events_Broadcast(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, orderId, second_toHHMMSS(data.remainTime))
                                end
                            end
                        elseif checkInt(data.status) == MaidCoffeeConstants.TakeOutStatus.Cold then
                            data.remainTime = checkInt(data.remainTime) - Elapsed
                            if data.remainTime <= 0 then
                                ---要重新请求订单信息
                                Events_Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = data, isNewOrder = 1 })

                            else
                                if checkInt(data.remainTime) > 0 then
                                    --local text = string.format_size_tag(string.format_color_tag(second_toHHMMSS(data.remainTime), '#d7184a'), 42)
                                    Events_Broadcast(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, orderId, data.remainTime)
                                end
                            end
                        end
                    end
                end
                if self.vipOrderRefreshTime > 0 then
                    self.vipOrderRefreshTime = checkInt(self.vipOrderRefreshTime) - Elapsed
                    if self.vipOrderRefreshTime <= 0 then
                        ----变成已完成
                        Events_Broadcast(Constants.EventNames.EVENT_VIP_ORDER_TIME_TICK, self.vipOrderRefreshTime, self.vipOrderId)
                    else
                        if checkInt(self.vipOrderRefreshTime) > 0 then
                            Events_Broadcast(Constants.EventNames.EVENT_VIP_ORDER_TIME_TICK, self.vipOrderRefreshTime, self.vipOrderId)
                        end
                    end
                end
            end, CountDownTime, false, true)
        end
    end

    if rawget(data,"vipOrderRefreshTime") then --@猫车订单刷新时间
        self.vipOrderRefreshTime = checkNumber(data.vipOrderRefreshTime)
    end

    if rawget(data,"vipOrderId") then  --@猫车订单id
        self.vipOrderId = checkNumber(data.vipOrderId)
    end

    if rawget(data,"cafeMenus") then --@经营菜单信息
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        component:InitialDojo({ menus = data.cafeMenus })
    end

    if rawget(data,"cafeAvatars") then  --@已拥有家具信息
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        component:InitialDojo({ cafeAvatars = data.cafeAvatars })
    end

    if rawget(data,"cafeViewScore") then --@家具积分
        self:UpdateAestheticsNum(data.cafeViewScore)
    end
end

