---GetCardsInTakeoutTeam
---获取当前外卖队伍中的所以卡牌列表
function MaidCoffeePlayerComponent:GetCardsInTakeoutTeam()
    local t = {}
    if self.teams and table.count(self.teams) > 0 then
        for _, cards in pairs(self.teams) do
            for i, id in pairs(cards) do
                if checkNumber(id) > 0 then
                    t[tostring(id)] = checkNumber(id)
                end
            end
        end
    end
    return t
end

function MaidCoffeePlayerComponent:FixTeams()
    local limitStatus2Status = MaidCoffeeUtils.GetMaidCoffeeCardStatusLimit(MaidCoffeeConstants.CafeStatus.InTakeaway)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local teams = self:GetAllTeam()
    local t = {}
    for teamIndex, cards in pairs(teams) do
        t[teamIndex] = t[teamIndex] or {}
        for index, playerCardId in pairs(cards) do
            local cardDojo = cardComponent:GetCardById(playerCardId)
            if cardDojo then
                if not limitStatus2Status[checkNumber(cardDojo.cafeStatus)] then
                    table.insert(t[teamIndex], playerCardId)
                end
            end
        end
    end
    self.teams = t
end

---ResetTakeoutOrders
---重置刷新下订单信息
---@param data table
function MaidCoffeePlayerComponent:ResetTakeoutOrders(data)
    data = checkTable(data)
    self.takeOutOrders = checkTable(data)
    for id, v in pairs(self.takeOutOrders) do
        ---添加id索引
        v.id = checkNumber(id)
    end
    if Events.HasListener(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED) then
        Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED)
    end
end

