---GetTakeoutOrdersByAreaId
---根据区域与位置获取订单
---@param areaId number
---@param position number
function MaidCoffeePlayerComponent:GetTakeoutOrdersByAreaId(areaId, position)
    local t = nil
    for _, v in pairs(self.takeOutOrders) do
        if checkNumber(v.area) == checkNumber(areaId) and checkNumber(v.position) == checkNumber(position) then
