---IsHaveFinishOrderByAreaId
---根据区域点来获取订单
---@param areaId number
function MaidCoffeePlayerComponent:IsHaveFinishOrderByAreaId(areaId)
    local isFinish = 0
    for _, v in pairs(self.takeOutOrders) do
        if checkNumber(v.area) == checkNumber(areaId) then
            if checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.FINISHED then
                isFinish = 1
                break
            end
        end
    end
    return isFinish
end

