---GetPacket
---获取所有道具
function MaidCoffeePlayerComponent:GetPacketByType(itemType)
    local configMgr = GoodsConfMgr:GetInstance()
    local t = {}
    for goodsId, num in pairs(self.packet) do
        if checkNumber(num) > 0 then
            local vo = configMgr:GetGoodsVoById(goodsId)
            if vo and checkNumber(vo.type) == itemType then
                table.insert(t, {
                    goodsId = goodsId,
                    num = num,
                    vo = vo
                })
            end
        end
    end
    return t
end

