---UpdateThingNo
---@param goodsId number 道具id
---@param extra table  如果是菜谱，现要添加其他信息 exp等exp需要是总值
function MaidCoffeePlayerComponent:UpdateThingNo(goodsId, extra)
    local type = GoodsUtils.GetIdType(goodsId)
    ---菜谱不会存在删除
    if type == Constants.IDType.RestaurantRecipeGoods then
        ---菜谱信息
        if self.packet[tostring(goodsId)] then
            ---已经存在的菜谱，进行信息更新
            local dojo = self.recipes[tostring(goodsId)]
            dojo.isCollect = checkNumber(extra.isCollect)
            dojo.exp = checkNumber(extra.exp)
            dojo.rating = checkNumber(extra.rating)
        else
            ----获得新的菜谱
            self.recipes[tostring(goodsId)] = RecipeDojo.New(goodsId, 0, 0, 1)
            self.packet[tostring(goodsId)] = 1
        end
    else
        if self.packet[tostring(goodsId)] then
            ---已经存在的菜谱，进行信息更新
            self.packet[tostring(goodsId)] = checkNumber(self.packet[tostring(goodsId)]) + checkNumber(extra.num)
        else
            ----获得新的菜谱
            self.packet[tostring(goodsId)] = checkNumber(extra.num)
        end
    end
end
---GetRecipeInfoByExp
---
---@param recipeId string
---@param exp number
function MaidCoffeePlayerComponent:GetRecipeInfoByExp(recipeId, exp)
    local vo = MaidCoffeeUtils.GetMaidCoffeeMenuMakeVo(recipeId)
    local rating = 1
    local leaveExp = 0
    local needExp = 0
    local isToMax = false
    local costExpAll = 0
    local curExp = 0
    if vo then
        for i, v in pairs(vo.experience) do
            curExp = curExp + tonumber(v)
            if exp >= curExp then
                costExpAll = curExp
                rating = i
            end
        end
    end
    if rating == #vo.experience then
        isToMax = true
    end
    if not isToMax then
        ---剩余经验值
        leaveExp = exp - costExpAll
        ---当前等级需要的值
        needExp = tonumber(vo.experience[rating + 1])
    end
    local data = { rating = rating, isToMax = isToMax, leaveExp = leaveExp, needExp = needExp }
    return data
end

