---UpdateRemoteTeamByTeamId
---@param teamId number
---@param cards table
---@param cb function
function MaidCoffeePlayerComponent:UpdateRemoteTeamByTeamId(teamId, cards, cb)
    local key = ''
    if #cards > 0 then
        key = table.concat(cards, ',')
    end
    GameUtils.Request(Interfaces.MaidCoffeeTakeoutSetTeam, { teamId = teamId, cards = key }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            ---成功了
            self.teams[tostring(teamId)] = checkTable(cards)
            if cb then
                cb()
            end
        end
    end)
end

function MaidCoffeePlayerComponent:IsHavePrivilegeCard()
    local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local isHavePrivilegeCard = false
    if playerDojo then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
    end
    return isHavePrivilegeCard
end

---GetTakeoutTeamStatus
---@param teamId number
function MaidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
    teamId = checkNumber(teamId)
    ---@type MaidCoffeeClerkSettingVo
    local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(teamId)
    local unlockType = checkNumber(vo.unlockType)
    local vip = checkNumber(vo.vip)
    local status = MaidCoffeeConstants.TakeOutStatus.LOCKED ---初始是锁定状态
    if vip == 0 then
        if GameUtils.IsUnlockedSingle(unlockType, checkNumber(vo.unlockNum)) then
            ---解锁状态
            status = MaidCoffeeConstants.TakeOutStatus.IDLE
            for _, v in pairs(self.takeOutOrders) do
                if checkNumber(v.unlocked) == 1 and (checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.PROGRESSING or checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.FINISHED) then
                    if checkNumber(v.teamId) == teamId then
                        status = checkNumber(v.status)
                        break
                    end
                end
            end
        end
    else
        ---如果是VIP情况下，看下特权卡是否存在
        if self:IsHavePrivilegeCard() then
            status = MaidCoffeeConstants.TakeOutStatus.IDLE ----已解锁了
            for _, v in pairs(self.takeOutOrders) do
                if checkNumber(v.unlocked) == 1 and (checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.PROGRESSING or checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.FINISHED) then
                    if checkNumber(v.teamId) == teamId then
                        status = checkNumber(v.status)
                        break
                    end
                end
            end
        end
    end
    return status
end

---GetTakeoutOrdersByTeamId
---获取编队正在关联的定单数据
---@param teamId number
function MaidCoffeePlayerComponent:GetTakeoutOrdersByTeamId(teamId)
    local vo = nil
    for _, v in pairs(self.takeOutOrders) do
        if checkNumber(v.unlocked) == 1 and (checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.PROGRESSING or checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.FINISHED) then
            if checkNumber(v.teamId) == teamId then
                vo = v
                break
            end
        end
    end
    return vo
end

