---IsHaveTakeOutReward
---是否有外卖订单奖励可领取
function MaidCoffeePlayerComponent:IsHaveTakeOutReward()
    local isUnLocked = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3003)
    if not isUnLocked then
        return false
    end
    local allOrders = self:GetAllTakeoutOrders()
    for i, v in pairs(allOrders) do
        if v.status == MaidCoffeeConstants.TakeOutStatus.FINISHED then
            return true
        end
    end
    return false
end

---IsAllTeamsIdle
---是否所有车队都空闲
function MaidCoffeePlayerComponent:IsAllTeamsIdle()
    local isUnLocked = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3003)
    if not isUnLocked then
        return false
    end
    local allOrders = self:GetAllTakeoutOrders()
    local index = 0
    for i, v in pairs(allOrders) do
        if  checkNumber(v.status) == MaidCoffeeConstants.TakeOutStatus.IDLE then
            index = index + 1
        end
    end
    if index == table.count(allOrders) then
        return true
    end
    return false
end

function MaidCoffeePlayerComponent:GetProgressingTakeOutTeamLeftTime()
    local leftTime = nil
    if self.takeOutOrders then
        for orderId, data in pairs(self.takeOutOrders) do
            if checkInt(data.status) == MaidCoffeeConstants.TakeOutStatus.PROGRESSING then
                local time = data.remainTime
                if isNull(leftTime) then
                    leftTime = time
                else
                    if time < leftTime then
                        leftTime = time
                    end
                end
            end
        end
    end
    return leftTime
end

function MaidCoffeePlayerComponent:GetTakeOutIgnoreTeamCardsData(_index)
    local t = {}
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    if self.teams and table.count(self.teams) > 0 then
        for index, cards in pairs(self.teams) do
            if index ~= tostring(_index) then
                for i, id in pairs(cards) do
                    if checkNumber(id) > 0 then
                        ---@type CardDojo
                        local cardDojo = cardComp:GetCardById(id)
                        t[tostring(cardDojo.cardId)] = checkNumber(id)
                    end
                end
            end
        end
    end
    return t
end

