--- GetAestheticsNum  获取美观度  checkIn需要同步
function MaidCoffeePlayerComponent:GetAestheticsNum()
    return self.aesthetics or 0
end

function MaidCoffeePlayerComponent:GetCurEffectIndex(num)
    local index
    local aestheticsNum = num or self:GetAestheticsNum()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting4112, "MaidCoffeeAestheticsVo", true)
    for i, v in pairs(allVos) do
        if aestheticsNum <= v.costValue then
            index = i
            break
        end
    end

    if isNull(index) and aestheticsNum > allVos[#allVos].costValue then
        index = #allVos
    end

    return index
end

function MaidCoffeePlayerComponent:UpdateAestheticsNum(num)
    self.aesthetics = num
end

function MaidCoffeePlayerComponent:RemoveTeamsPlayerId(id)
    local isFind = false
    for k, v in pairs(self.teams) do
        for i, j in pairs(v) do
            if j == id then
                v[i] = nil
                isFind = true
                break
            end
        end
        if isFind then
            break
        end
    end
end

function MaidCoffeePlayerComponent:IsShowVipOrderRedPoint()
    local isVipOrderUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3004)
    if isVipOrderUnlock then
        local vipOrderId, time = self:GetVipOrderTime()
        if checkNumber(vipOrderId) == 0 or time <= 0 then
            return true
        end
    end
    return false
end

function MaidCoffeePlayerComponent:GetTakeOutNumData()
    local area = ActionUtils.GetAllRegionPrimaryMapVo()
    local totalNum = 0
    local totalCompleteNum = 0
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    for i, v in pairs(area) do
        if not isNull(v) then
            local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(v.id)
            local isUnlock = ActionUtils.IsUnlockRegionalPoint(v.id)
            if isUnlock then
                local timeLimitVo =  CfUtils.GetCfVo(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",v.id)
                local maxNum = timeLimitVo.takeOutNum[lv]
                totalNum = totalNum + maxNum
                totalCompleteNum = totalCompleteNum + self:GetTimeByArea(v.id)
            end
        end
    end
    return {totalNum = totalNum, leaveNum = totalNum - totalCompleteNum }
end

function MaidCoffeePlayerComponent:GetAreaTakeOutLeaveTime(areaId)
    local vo = ActionUtils.GetRegionPrimaryMapVo(areaId)
    local timeLimitVo = CfUtils.GetCfVo(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",areaId)
    if vo then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local lv, _ = ActionUtils.GetRegionalPointLikabilityLevel(vo.id)
        if timeLimitVo then
            local maxCount = timeLimitVo.takeOutNum[lv]
            return maxCount - self:GetTimeByArea(areaId)
        end
    end
    return 0
end

return MaidCoffeePlayerComponent